  // src/phaser/BootScene.ts
  var BootScene = class extends Phaser2.Scene {
    constructor() {
      super({ key: "BootScene" });
    }
    init(data) {
      this.bridge = data.bridge;
    }
    create() {
      generateAllPixelTextures(this);
      const preview = typeof window !== "undefined" && new URLSearchParams(window.location.search).get("erpreview");
      this.bridge.onBootReady();
      if (preview) {
        this.scene.stop();
        return;
      }
      this.scene.start("EuropeMapScene", { bridge: this.bridge });
    }
  };

