  function evaluateCollisionFault(kind, playerX, playerY, playerRot, playerSpeed, otherX, otherY, otherSpeed) {
    if (kind === "obstacle") {
      return { playerAtFault: true, reason: "Du hast ein Hindernis bzw. eine Baustellen-Absperrung gestreift." };
    }
    const absSpd = Math.abs(playerSpeed);
    if (absSpd <= 18) {
      return {
        playerAtFault: false,
        reason: "Dein Fahrzeug stand vorschriftsm\xE4\xDFig \u2013 der andere Verkehrsteilnehmer ist aufgefahren."
      };
    }
    if (kind === "pedestrian") {
      return {
        playerAtFault: true,
        reason: "Du bist im Fu\xDFg\xE4nger-/Zebrastreifen-Bereich zu schnell an einem Passanten vorbeigefahren."
      };
    }
    if (kind === "cyclist") {
      return {
        playerAtFault: true,
        reason: "Zu geringer Seitenabstand beim \xDCberholen bzw. Kreuzen des Radwegs."
      };
    }
    const fx = Math.sin(playerRot) * (playerSpeed >= 0 ? 1 : -1);
    const fy = -Math.cos(playerRot) * (playerSpeed >= 0 ? 1 : -1);
    const dx = otherX - playerX;
    const dy = otherY - playerY;
    const dist = Math.max(1, Math.hypot(dx, dy));
    const impactInFront = dx / dist * fx + dy / dist * fy;
    if (impactInFront < -0.25 && otherSpeed > absSpd * 0.8) {
      return {
        playerAtFault: false,
        reason: "Ein anderer Pkw ist dir hinten/seitlich aufgefahren, w\xE4hrend du bereits abgebremst hast."
      };
    }
    if (absSpd < 42 && otherSpeed > 75 && impactInFront < 0.35) {
      return {
        playerAtFault: false,
        reason: "Der kreuzende Verkehr hat deine Vorfahrt missachtet."
      };
    }
    return {
      playerAtFault: true,
      reason: "Du bist mit zu hoher Geschwindigkeit in das andere Fahrzeug gefahren."
    };
  }

