  // src/sim/RouteNavigation.ts
  function stageDestination(run, leg, index, city) {
    if (leg.citySegmentAtEnd === "hannover_messe") return "Hannover Messe";
    if (leg.overnightAtEnd && !run.triggeredEventIds.includes(`evt_hotel_overnight@${index}`)) return `\xDCbernachtung \xB7 ${city}`;
    if (leg.destinationAtEnd) return city;
    if (leg.citySegmentAtEnd === "ferry_denmark") return `F\xE4hrterminal \xB7 ${city}`;
    if (leg.citySegmentAtEnd === "aachen_finish") return city;
    return void 0;
  }
  function buildRemainingRoute(level, run) {
    const legs = getActiveRouteLegs(level, run.plan);
    const vehicle = getVehicleById(run.plan.vehicleId);
    const route = { destination: "", segments: [], remainingKm: 0, etaMinutes: 0 };
    for (let index = run.currentLegIndex; index < legs.length; index++) {
      const leg = legs[index];
      const edge = getEdgeById(leg.edgeId);
      const current = index === run.currentLegIndex;
      const from = getCityById(leg.reverse ? edge.toCityId : edge.fromCityId).name;
      const to = getCityById(leg.reverse ? edge.fromCityId : edge.toCityId).name;
      const startKm = current ? Math.max(0, Math.min(edge.distanceKm, run.legProgressKm)) : 0;
      const charger = plannedRoadStopsOnLeg(run.plan, leg, index).find(
        ({ stop, progress }) => progress * edge.distanceKm >= startKm && isPendingStop(run, stop)
      );
      const endKm = charger ? charger.progress * edge.distanceKm : edge.distanceKm;
      const remainingKm = endKm - startKm;
      const destination = charger?.station.name ?? stageDestination(run, leg, index, to) ?? (index === legs.length - 1 ? to : void 0);
      if (remainingKm > 0 || destination) {
        route.segments.push({ highwayName: edge.highwayName, from, to: charger?.station.name ?? to, remainingKm, current });
      }
      route.remainingKm += remainingKm;
      const weather = current ? run.activeWeather : leg.weatherOverride ?? edge.defaultWeather;
      const setSpeed = run.plan.legPlans.find((plan) => plan.legIndex === index)?.targetSpeedKmh ?? defaultLegSpeedKmh(edge, vehicle.maxSpeedKmh, weather);
      const cruise = congestedCruiseKmh(snapSpeedKmh(setSpeed, vehicle.maxSpeedKmh), edge.baseTrafficRisk);
      const cap = current ? run.speedCapKmh ?? run.countryLimitKmh : void 0;
      const etaSpeed = cap && cap > 0 ? Math.min(cap, cruise) : cruise;
      route.etaMinutes += remainingKm / etaSpeed * 60;
      if (!charger && leg.citySegmentAtEnd) {
        route.etaMinutes += CITY_TRANSITION_MINUTES[leg.citySegmentAtEnd] ?? 0;
      }
      if (destination) {
        route.destination = destination;
        break;
      }
    }
    return route;
  }

  // src/ui/DrivingStatus.ts
  function formatClock(level, elapsedMin) {
    const total = Math.round(level.departureTimeHour * 60 + elapsedMin);
    const hh = String(Math.floor(total / 60) % 24).padStart(2, "0");
    const mm = String(total % 60).padStart(2, "0");
    return `${hh}:${mm}`;
  }
  function formatDrivingCosts(run) {
    return totalRunCost(run).toFixed(2) + " \u20AC";
  }
  function renderDriveStatus(level, run) {
    return `<div class="er-modal-drive-status" aria-label="Fahrtstatus beim \xD6ffnen">
    <span>Hunger <b>${Math.round(run.hungerNeed)} %</b></span>
    <span>Akku <b>${Math.round(run.socPct)} %</b></span>
    <span>Stress <b>${Math.round(run.stress)} %</b></span>
    <span>Ausgaben <b>${formatDrivingCosts(run)}</b></span>
    <time>${formatClock(level, run.elapsedMinutes)}</time>
  </div>`;
  }

  // src/ui/DrivingHUD.ts
  function renderStageComputer(edge, progress, reverse, tollsEur, pauseCostEur) {
    const pts = getEdgeWaypoints(edge, reverse);
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    pts.forEach((p) => {
      minX = Math.min(minX, p.x);
      minY = Math.min(minY, p.y);
      maxX = Math.max(maxX, p.x);
      maxY = Math.max(maxY, p.y);
    });
    const w = 210;
    const h = 96;
    const pad = 10;
    const sx = Math.max(1, maxX - minX);
    const sy = Math.max(1, maxY - minY);
    const scale = Math.min((w - pad * 2) / sx, (h - pad * 2) / sy);
    const ox = (w - sx * scale) / 2;
    const oy = (h - sy * scale) / 2;
    const project = (p) => ({ x: ox + (p.x - minX) * scale, y: oy + (p.y - minY) * scale });
    const mapped = pts.map(project);
    const d = mapped.map((p, i) => `${i === 0 ? "M" : "L"}${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(" ");
    const dot = project(getPointAlongEdge(edge, progress, reverse));
    return `
    ${edge.tollEur > 0 || tollsEur > 0 ? `<div class="trip-road">Maut bisher ${tollsEur.toFixed(2)} \u20AC \xB7 Etappe ${edge.tollEur.toFixed(2)} \u20AC</div>` : ""}
    ${pauseCostEur > 0 ? `<div class="trip-road">Pausen bisher ${pauseCostEur.toFixed(2)} \u20AC</div>` : ""}
    <svg viewBox="0 0 ${w} ${h}" class="stage-map" aria-hidden="true">
      <path d="${d}" fill="none" stroke="rgba(148,163,184,0.85)" stroke-width="4" stroke-linecap="round" />
      <circle cx="${dot.x.toFixed(1)}" cy="${dot.y.toFixed(1)}" r="5.5" fill="#38bdf8" stroke="#f8fafc" stroke-width="2" />
    </svg>
  `;
  }
